- Backpressure, batching, and failure isolation
- Stateless versus stateful sinks and lifecycle management

## Code Example

```javascript
interface TelemetrySink {
  send(event: TelemetryEvent): Promise<void>;
  flush?(): Promise<void>;
  shutdown?(): Promise<void>;
}

class PluginRegistry {
  #sinks = new Map();

  register(name, factory) {
    this.#sinks.set(name, factory(this));
  }

  get(name) {
    return this.#sinks.get(name);
  }

  list() {
    return Array.from(this.#sinks.keys());
  }
}

class SyslogSink {
  #buffer = [];
  #batchSize = 100;
  #flushInterval = 5000;
  #paused = false;
  #controller = new AbortController();

  constructor(options = {}) {
    this.#batchSize = options.batchSize ?? 100;
    this.#flushInterval = options.flushInterval ?? 5000;
    this.#startFlushTimer();
  }

  async send(event) {
    if (this.#paused) {
      throw new Error('Backpressure: sink is paused');
    }

    this.#buffer.push(event);

    if (this.#buffer.length >= this.#batchSize) {
      await this.flush();
    }

    if (this.#buffer.length > this.#batchSize * 0.8) {
      this.#paused = true;
    }
  }

  async flush() {
    if (this.#buffer.length === 0) return;

    const batch = this.#buffer.splice(0, this.#batchSize);
    try {
      await this.#sendToSyslog(batch);
      this.#paused = false;
    } catch (err) {
      this.#buffer.unshift(...batch);
      throw err;
    }
  }

  async shutdown() {
    this.#controller.abort();
    await this.flush();
  }

  #startFlushTimer() {
    setInterval(() => this.flush(), this.#flushInterval);
  }

  async #sendToSyslog(batch) {
    // Send batch to syslog endpoint
  }
}

// Usage
const registry = new PluginRegistry();
registry.register('syslog', () => new SyslogSink({ batchSize: 50 }));
```

## Why This Is Asked

Evaluates understanding of the Memento pattern for encapsulating state and enabling undo/redo without exposing internals, plus extensibility for new operations.

## Key Concepts

- Memento pattern with Originator, Memento, Caretaker
- Encapsulation of internal state
- History navigation (undo/redo) via a caretaker
- Extensibility to add new operations without modifying the originator

## Code Example

```javascript
class EditorOriginator {
  constructor(text = "") { this.text = text; }
  createMemento() { return new EditorMemento(this.text); }
  restore(m) { this.text = m.getState(); }
  insert(pos, ch) { this.text = this.text.slice(0, pos) + ch + this.text.slice(pos); }
  delete(pos, len) { this.text = this.text.slice(0, pos) + this.text.slice(pos + len); }
}
class EditorMemento { constructor(state) { this._state = state; } getState() { return this._state; } }
class Caretaker {
  constructor() { this.history = []; this.index = -1; }
  push(m) { this.history = this.history.slice(0, this.index + 1).concat([m]); this.index++; }
  undo() { if (this.index <= 0) return null; this.index--; return this.history[this.index + 1]; }
  redo() { if (this.index + 1 >= this.history.length) return null; this.index++; return this.history[this.index]; }
}
```

